/* Offline support for the arcade. Generated by tools/update-sw.py: edit tools/sw-template.js, not sw.js.
   - install: download every page and icon in one go (the install only succeeds if all of them were saved)
   - fetch: answer from the saved copy straight away, then quietly refresh it in the background
   - activate: delete the copies saved by older versions */
const VERSION = 'games-c2ca3c227799';
const FILES = [
  './',
  './manifest.webmanifest',
  './icons/apple-touch-icon.png',
  './icons/favicon-32.png',
  './icons/icon-192.png',
  './icons/icon-512.png',
  './icons/logo.jpg',
  './icons/maskable-512.png',
  './bean-merge/',
  './bumble-dash/',
  './busy-beaver/',
  './dot-loop/',
  './dots-and-boxes/',
  './guess-five/',
  './gummy-pop/',
  './hedge-hop/',
  './ink-bounce/',
  './pyramid-hop/',
  './slither-slide/',
  './stack-drop/',
  './sudoku/',
  './tangle-tails/',
  './tile-burst/',
  './word-hive/'
];

self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(VERSION)
      .then(cache => cache.addAll(FILES.map(url => new Request(url, { cache: 'reload' }))))
      .then(() => self.skipWaiting())
  );
});

self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys()
      .then(keys => Promise.all(keys.filter(k => k.startsWith('games-') && k !== VERSION).map(k => caches.delete(k))))
      .then(() => self.clients.claim())
  );
});

self.addEventListener('fetch', event => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  // one key per page: ignore ?query and treat folder/index.html as folder/
  let path = url.pathname;
  if (path.endsWith('/index.html')) path = path.slice(0, -'index.html'.length);
  const key = new Request(url.origin + path);
  event.respondWith((async () => {
    const cache = await caches.open(VERSION);
    const saved = await cache.match(key);
    const fresh = fetch(req).then(res => {
      if (res && res.ok && res.type === 'basic') cache.put(key, res.clone());
      return res;
    }).catch(() => null);
    if (saved) { event.waitUntil(fresh); return saved; }
    const res = await fresh;
    if (res) return res;
    if (req.mode === 'navigate') return (await cache.match(new Request(new URL('./', self.location).href))) || Response.error();
    return Response.error();
  })());
});
